// Flag slices wasting budget vs the account's own cost-per-result benchmark:
// zero results with real spend, or a cost-per-result far above benchmark.
// "At risk" = dollars spent above what benchmark efficiency would have cost.
const { slices, skipped, benchmarkCPR, acctSpend, acctResults, cfg } = $json;
const FLOOR = cfg.SPEND_FLOOR, MULT = cfg.CPR_MULTIPLE;

const wasted = (slices || [])
  .filter((s) => s.spend >= FLOOR && (s.results === 0 || (benchmarkCPR && s.cpr > benchmarkCPR * MULT)))
  .map((s) => ({
    ...s,
    waste_type: s.results === 0 ? 'zero_results' : 'high_cost_per_result',
    at_risk: s.results === 0 ? s.spend : +Math.max(0, s.spend - s.results * benchmarkCPR).toFixed(2),
  }))
  .sort((a, b) => b.at_risk - a.at_risk)
  .slice(0, 20);

const total_at_risk = +wasted.reduce((n, s) => n + s.at_risk, 0).toFixed(2);
return [{ json: { wasted, total_at_risk, benchmarkCPR, acctSpend, acctResults, skipped, floor: FLOOR, cpr_multiple: MULT, considered: (slices || []).length } }];

// Ask Claude to rank the kill list and recommend a concrete action per slice.
const { wasted, total_at_risk, benchmarkCPR } = $json;
const system = 'You are a senior paid-media analyst. You are given underperforming delivery slices from a Meta ad account, judged against the account cost-per-result benchmark. Rank them by dollars recoverable, and for each give a one-line rationale and one concrete action: pause, exclude, or reallocate. Be specific and terse. Return ONLY valid JSON, no prose.';
const user = 'Account cost-per-result benchmark: $' + benchmarkCPR + '. Total at risk: $' + total_at_risk + '.\n\nSlices:\n' + JSON.stringify(wasted) + '\n\nReturn JSON exactly: {"summary":"one sentence","ranked":[{"slice":"","dimension":"","at_risk":0,"action":"pause|exclude|reallocate","why":""}]}';
const body = { model: 'claude-haiku-4-5', max_tokens: 1500, system, messages: [{ role: 'user', content: user }] };
return [{ json: { body, _ctx: $json } }];

// Print the ranked wasted-spend report to stdout. Extract the JSON object by
// braces so model code-fences never break parsing.
const ctx = $node['Flag underperforming slices vs benchmark'].json;
const raw = ($json.content && $json.content[0] && $json.content[0].text) || '{}';
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
let parsed = { summary: '(could not parse model output)', ranked: [] };
try { parsed = JSON.parse(raw.slice(s, e + 1)); } catch (err) {}

const out = [];
out.push('');
out.push('==========================================================');
out.push('  META ADS WASTED-SPEND FINDER  |  nocode.expert');
out.push('==========================================================');
out.push('Account cost-per-result benchmark: $' + ctx.benchmarkCPR + '  (' + ctx.acctResults.toLocaleString() + ' results on $' + ctx.acctSpend.toLocaleString() + ')');
if (ctx.skipped && ctx.skipped.length) {
  out.push('Skipped (no conversion attribution): ' + ctx.skipped.map((x) => x.dimension).join(', '));
}
out.push('Total at risk: $' + (ctx.total_at_risk || 0).toLocaleString());
out.push('');
out.push(parsed.summary || '');
out.push('');
(parsed.ranked || []).forEach((r, i) => {
  out.push(String(i + 1).padStart(2) + '. [$' + (r.at_risk || 0).toLocaleString() + ']  ' + r.dimension + ' :: ' + r.slice);
  out.push('     -> ' + String(r.action || '').toUpperCase() + ': ' + (r.why || ''));
});
out.push('==========================================================');
console.log(out.join('\n'));
return [{ json: parsed }];

// Sum configured result events on the account total and compute the
// cost-per-result benchmark. Pure data transform, no API calls.
const cfg = $('Set config: result events, floor').first().json;
const RES = new Set(cfg.RESULT_ACTIONS);
const resultsOf = (a) => Array.isArray(a)
  ? a.filter(x => RES.has(x.action_type)).reduce((n,x)=>n+(Number(x.value)||0),0) : 0;
const acct = ($json.data && $json.data[0]) || {};
const acctSpend = Number(acct.spend) || 0;
const acctResults = resultsOf(acct.actions);
const benchmarkCPR = acctResults > 0 ? +(acctSpend/acctResults).toFixed(2) : null;
return [{ json: { acctSpend:+acctSpend.toFixed(2), acctResults, benchmarkCPR } }];

// Emit one item per delivery breakdown. The next Facebook node then runs once
// per item, so n8n loops over the breakdowns for you. Pure data transform.
const cfg = $('Set config: result events, floor').first().json;
const BREAKDOWNS = [
  { dim: 'placement',  breakdowns: 'publisher_platform,platform_position' },
  { dim: 'region',     breakdowns: 'region' },
  { dim: 'age_gender', breakdowns: 'age,gender' },
  { dim: 'hour',       breakdowns: 'hourly_stats_aggregated_by_advertiser_time_zone' },
];
return BREAKDOWNS.map(b => ({ json: { ...b, DATE_PRESET: cfg.DATE_PRESET } }));

// Combine the four breakdown responses into per-slice rows, apply the attribution
// gate (skip a breakdown that loses most results), attach cost-per-result.
// Pure data transform over the Facebook node responses.
const cfg = $('Set config: result events, floor').first().json;
const bench = $('Compute benchmark').first().json;
const reqs = $('List delivery breakdowns').all();
const RES = new Set(cfg.RESULT_ACTIONS);
const resultsOf = (a) => Array.isArray(a)
  ? a.filter(x => RES.has(x.action_type)).reduce((n,x)=>n+(Number(x.value)||0),0) : 0;
const LABEL = {
  placement:  (r) => `${r.publisher_platform} / ${r.platform_position}`,
  region:     (r) => r.region,
  age_gender: (r) => `${r.age} ${r.gender}`,
  hour:       (r) => (r.hourly_stats_aggregated_by_advertiser_time_zone || '').slice(0,5),
};
const responses = $input.all();
const slices = [], skipped = [];
responses.forEach((item, i) => {
  const dim  = reqs[i].json.dim;
  const rows = item.json.data || [];
  const bResults = rows.reduce((n,r)=>n+resultsOf(r.actions),0);
  if (bench.acctResults > 0 && bResults < bench.acctResults * cfg.MIN_ATTRIBUTION) {
    skipped.push({ dimension: dim, captured: bResults, of: bench.acctResults }); return;
  }
  for (const r of rows) {
    const spend = Number(r.spend)||0, results = resultsOf(r.actions);
    slices.push({ dimension: dim, slice: LABEL[dim](r), spend:+spend.toFixed(2), results, cpr: results>0 ? +(spend/results).toFixed(2) : null });
  }
});
return [{ json: { slices, skipped, benchmarkCPR: bench.benchmarkCPR, acctSpend: bench.acctSpend, acctResults: bench.acctResults, cfg } }];

// Nothing crossed the waste thresholds. Keep the shape the report expects.
console.log('No delivery slices exceeded the waste thresholds. Nothing to cut.');
return [{ json: { summary: 'No wasted spend found', ranked: [] } }];

// Tune the finder here. RESULT_ACTIONS is every event that counts as a "result"
// (leads, registrations, purchases) - the workflow sums whichever are present,
// so it works for lead-gen and ecommerce without code changes.
return [{ json: {
  DATE_PRESET: 'last_30d',
  SPEND_FLOOR: 300,        // ignore slices below this spend
  CPR_MULTIPLE: 2,         // flag a slice if its cost-per-result is this many times the account benchmark
  MIN_ATTRIBUTION: 0.5,    // skip a breakdown if it captures under this share of account results (attribution gap)
  RESULT_ACTIONS: [
    'offsite_complete_registration_add_meta_leads', 'lead', 'leadgen_grouped',
    'onsite_conversion.lead_grouped', 'omni_complete_registration', 'complete_registration',
    'omni_purchase', 'offsite_conversion.fb_pixel_purchase', 'purchase',
  ],
} }];
